def merge_intervals(intervals):
    """Return non-overlapping [start, end] pairs covering the same points,
    sorted by start. Touching intervals (end == next start) are merged."""
    if not intervals:
        return []
    merged = []
    for start, end in sorted(intervals, key=lambda iv: iv[0]):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
